import{z as A,x as T,o as E,c as i,q as d,j as c,D as o,d as s,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"集合运算与 EXISTS","description":"","frontmatter":{"title":"集合运算与 EXISTS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/set-ops-exists.md","filePath":"cs/set-ops-exists.md","lastUpdated":1791063341000}'),n={name:"cs/set-ops-exists.md"};function N(l,e,B,S,p,I){const a=T("Mermaid");return E(),i("div",null,[e[2]||(e[2]=d('<h1 id="集合运算与-exists" tabindex="-1">集合运算与 EXISTS <a class="header-anchor" href="#集合运算与-exists" aria-label="Permalink to &quot;集合运算与 EXISTS&quot;">​</a></h1><div class="epigraph"><p>并交差是关系代数的原语；EXISTS 是演算里的存在量词。SQL 两者都给，指称要对齐，NULL 与包会把对齐撕开一条缝。</p><footer>—— 据 Codd 关系代数与元组演算；Date 对 EXISTS；Ramakrishnan and Gehrke 整理</footer></div><p><a href="/cs/recursive-cte">上一课</a>用迭代并逼近传递闭包。本课不重写不动点。缺口是日常查询里的<strong>集合级对照</strong>：<code>UNION</code>/<code>INTERSECT</code>/<code>EXCEPT</code>，以及 <code>EXISTS</code>/<code>NOT EXISTS</code>。主干代数课有并交差，SQL 声明课点到 <code>UNION</code>；进阶要把包版本、对应列、存在量化与半连接一次钉清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户写「在 A 不在 B」「A 与 B 都有的键」。用 <code>NOT IN</code> 子查询遇到 NULL 会得到 UNKNOWN，整句滤掉过多行——<a href="/cs/sql-null">三值</a> 已警告。<code>NOT EXISTS</code> 按行相关探测内层是否非空，对 NULL 更符合「不存在匹配」的直觉。缺口不是再讲嵌套语法，而是<strong>集合运算与存在量化何时同指称、何时必须分开</strong>。</p><p><code>UNION</code> 去重，<code>UNION ALL</code> 保留包计数。<code>INTERSECT</code>/<code>EXCEPT</code> 同样有 ALL 变体。对应列要可比较、模式对齐。集合运算两侧先投影到同一目，再做袋或集合运算。</p><p><span class="marginnote">Codd 的演算用 ∃ 表达连接与选择。SQL 的 <code>EXISTS (SELECT * FROM …)</code> 不关心投影列，只关心非空。半连接实现它；反半连接实现 <code>NOT EXISTS</code>。去相关课已用过这组算子，本课从语言对照补齐。</span></p><p><span class="marginnote">数字实例：<code>WHERE id NOT IN (1, 2, NULL)</code>——对 id=3，<code>3 &lt;&gt; NULL</code> 的结果是 UNKNOWN 而不是 TRUE，整行被过滤。所以列表里只要混进一个 NULL，<code>NOT IN</code> 就把结果掏成空集；换成 <code>NOT EXISTS</code> 没有这颗雷。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集合运算：两输入关系（包）模式兼容 → 并/交/差。优化器可把 <code>EXCEPT</code> 变成反半连接或哈希差。<code>EXISTS</code>：对每个外层行求内层是否非空，允许内层一旦找到一行就停。<code>IN</code> 列表是等值存在，遇 NULL 走三值；能改写为半连接时必须复制该三值行为，否则指称错。</p><p>相关 <code>EXISTS</code> 与不相关 <code>EXISTS</code>：后者可先判一次真假；前者依赖外层。本课不把 <code>UNIQUE</code> 谓词、<code>MATCH</code> 的全部标准角落写完。</p>',11)),(E(),c(r,null,{default:o(()=>[t(a,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALG%5B%22%E5%B9%B6%20%2F%20%E4%BA%A4%20%2F%20%E5%B7%AE%22%5D%20--%3E%20BAG%5B%22ALL%3A%20%E5%8C%85%E8%AE%A1%E6%95%B0%22%5D%0A%20%20ALG%20--%3E%20SET%5B%22%E6%97%A0%20ALL%3A%20%E5%8E%BB%E9%87%8D%22%5D%0A%20%20EX%5B%22EXISTS%22%5D%20--%3E%20SJ%5B%22%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20NEX%5B%22NOT%20EXISTS%22%5D%20--%3E%20ASJ%5B%22%E5%8F%8D%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20INP%5B%22IN%20%2F%20NOT%20IN%22%5D%20--%3E%20TV%5B%22%E4%B8%89%E5%80%BC%E9%99%B7%E9%98%B1%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>执行上，哈希差与排序归并差对应两种物理形状，与连接算法同源：一边建哈希或两边排序。<code>EXISTS</code> 短路径：内层有索引时相关探测很便宜，这是去相关课「保留 NLJ」的例子。<code>UNION</code> 后的 <code>ORDER BY</code> 只对总结果排序，不能假设某一侧的序还在。</p><p>上面那张图把算子和它的指称对上号；下面这张把 <code>NOT EXISTS</code> 的相关执行走一遍——为什么内层有索引它就便宜。</p>',3)),(E(),c(r,null,{default:o(()=>[t(a,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%96%E5%A4%96%E5%B1%82%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20B%5B%22%E7%94%A8%E7%B4%A2%E5%BC%95%E6%8E%A2%E6%B5%8B%E5%86%85%E5%B1%82%22%5D%0A%20%20B%20--%3E%20C%7B%22%E5%86%85%E5%B1%82%E6%89%BE%E5%88%B0%E4%B8%80%E8%A1%8C%3F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20D%5B%22%E8%AF%A5%E5%A4%96%E5%B1%82%E8%A1%8C%E8%A2%AB%E6%8E%92%E9%99%A4%22%5D%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20E%5B%22%E8%AF%A5%E5%A4%96%E5%B1%82%E8%A1%8C%E4%BF%9D%E7%95%99%22%5D%0A%20%20D%20--%3E%20F%5B%22%E7%BB%A7%E7%BB%AD%E4%B8%8B%E4%B8%80%E8%A1%8C%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%7B%22%E5%A4%96%E5%B1%82%E8%BF%98%E6%9C%89%E8%A1%8C%3F%22%7D%0A%20%20G%20--%20%22%E6%98%AF%22%20--%3E%20A%0A%20%20G%20--%20%22%E5%90%A6%22%20--%3E%20H%5B%22%E8%BE%93%E5%87%BA%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">直觉类比：<code>EXISTS</code> 像点名只问「有没有人举手」——内层扫到第一行匹配就立刻停（短路），不必翻完整张表；<code>COUNT</code> 则必须点完。这就是「只关心非空」换来的执行便宜。</span></p><p><span class="marginnote">常见误区：以为 <code>UNION</code> 两侧各写 ORDER BY，合并结果仍保持各自的序。实际上只有最外层的 <code>ORDER BY</code> 作数；内侧的排序不保证保留，优化器还可能直接剪掉——想有序，只在最外层排。</span></p><p>递归 CTE 的 <code>UNION</code> 与本课 <code>UNION</code> 同一代数，只是一侧在迭代中增长。本课不回头重讲停机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把外连接引进来：外连接保留未匹配侧并填 NULL，与差、反半连接都不同。下一课专讲外连接与半连接的对照。也不把集合运算当完整性约束的替代——约束是后课触发器与声明约束。</p><p>后课默认：写「不存在」优先考虑 <code>NOT EXISTS</code> 或差，而不是 <code>NOT IN</code> 碰 NULL。集合运算是代数原语，存在量化是演算原语，计划上常汇合到半连接族。</p><p>包与集合必须在语句里显式选择（ALL 或否），不能靠引擎「顺便去重」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>UNION</code>/<code>INTERSECT</code>/<code>EXCEPT</code> 有集合与包两档；模式必须对齐。</li><li><code>EXISTS</code> 即半连接；<code>NOT IN</code> 与 <code>NOT EXISTS</code> 在 NULL 下不同指称。</li><li>外连接与半连接下一课，补「保留未匹配」。</li><li>出处：Codd；Date；Ramakrishnan and Gehrke。</li></ul>',9))])}const D=A(n,[["render",N]]);export{L as __pageData,D as default};
